import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"宾之初筵","description":"","frontmatter":{"title":"宾之初筵","date":"2026-11-08T00:00:00.000Z","seq":60,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/宾之初筵.md","filePath":"blogs/诗经·小雅/宾之初筵.md"}'),o={name:"blogs/诗经·小雅/宾之初筵.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="宾之初筵" tabindex="-1">宾之初筵 <a class="header-anchor" href="#宾之初筵" aria-label="Permalink to &quot;宾之初筵&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　甫田之什</p><div class="poem"><p class="poem-stanza">宾之初筵，左右秩秩。笾豆有楚，殽核维旅。酒既和旨，饮酒孔偕。</p><p class="poem-stanza">钟鼓既设，举酬逸逸。大侯既抗，弓矢斯张。射夫既同，献尔发功。</p><p class="poem-stanza">发彼有的，以祈尔爵。</p><p class="poem-stanza">籥舞笙鼓，乐既和奏。烝衎烈祖，以洽百礼。百礼既至，有壬有林。</p><p class="poem-stanza">锡尔纯嘏，子孙其湛。其湛曰乐，各奏尔能。宾载手仇，室人入又。</p><p class="poem-stanza">酌彼康爵，以奏尔时。</p><p class="poem-stanza">宾之初筵，温温其恭。其未醉止，威仪反反。曰既醉止，威仪幡幡。</p><p class="poem-stanza">舍其坐迁，屡舞仙仙。其未醉止，威仪抑抑。曰既醉止，威仪抑抑。</p><p class="poem-stanza">是曰既醉，不知其秩。</p><p class="poem-stanza">宾既醉止，载号载呶。乱我笾豆，屡舞僛僛。是曰既醉，不知其邮。</p><p class="poem-stanza">侧弁之俄，屡舞傞傞。既醉而出，并受其福。醉而不出，是谓伐德。</p><p class="poem-stanza">饮酒孔嘉，维其令仪。</p><p class="poem-stanza">凡此饮酒，或醉或否。既立之监，或佐之史。彼醉不臧，不醉反耻。</p><p class="poem-stanza">式勿从谓，无俾大怠。匪言勿言，匪由勿语。由醉之言，俾出童羖。</p><p class="poem-stanza">三爵不识，矧敢多又。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
